-- 0038_dedup_catalog.sql - the course dedup, CATALOG half (founder
-- directive 2026-10-21: "clear those duplicate and remain only one in
-- each of their origin department").
--
-- Runs AFTER 0037 (the user half) on the same journal:
--   USER pool  : student rows were already repointed, so the deletes
--                below cascade onto nothing the students still use.
--   CONTENT pool (Supabase): this file IS the dedup - the retired
--                courses and their topics leave the live catalog.
--   CACHE pool : the local catalog copy (if any) is cleaned too; stale
--                learn.lessons rows keyed by retired topics become
--                unreachable orphans and simply age out.
--
-- learn.topics, learn.lessons (on the pools that hold them) and
-- learn.course_units all carry ON DELETE CASCADE from learn.courses,
-- so deleting the retired course rows retires their topics, cached
-- lessons and AI-expanded units with them.
--
-- The eight national-suite titles the founder's shelf re-homes
-- (Use of English, Peace & Conflict Resolution, SIWES family, ...)
-- move to the GST-ALL general-studies department first.
--
-- Idempotent: re-running deletes nothing (the map is empty).

CREATE TABLE IF NOT EXISTS learn.dedup_course_map (
  retired TEXT PRIMARY KEY,
  keep    TEXT NOT NULL
);
